parameters.jsCode:
// Parsear respuesta de Gemini
const geminiResponse = $input.first().json;

try {
  const candidates = geminiResponse.candidates || [];
  if (candidates.length === 0) {
    return { json: { error: 'Sin respuesta de Gemini' } };
  }

  const text = candidates[0].content?.parts?.[0]?.text || '';

  // Extraer JSON del texto
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (!jsonMatch) {
    return { json: { error: 'Formato inválido', raw: text } };
  }

  const analisis = JSON.parse(jsonMatch[0]);

  return {
    json: {
      patente: $node["Normalizar Datos"].first().json.patente,
      marca: $node["Normalizar Datos"].first().json.marca,
      modelo: $node["Normalizar Datos"].first().json.modelo,
      anio: $node["Normalizar Datos"].first().json.anio,
      precio: $node["Normalizar Datos"].first().json.precio,
      link: $node["Normalizar Datos"].first().json.link,
      telefono: $node["Normalizar Datos"].first().json.telefono,
      score: analisis.score || 5,
      riesgos: analisis.riesgos || [],
      recomendacion: analisis.recomendacion || 'EVALUAR',
      resumen: analisis.resumen || '',
      timestamp: new Date().toISOString()
    }
  };
} catch (error) {
  return {
    json: {
      error: error.message,
      patente: $node["Normalizar Datos"].first().json.patente,
      score: 5,
      riesgos: ['Error al analizar'],
      recomendacion: 'EVALUAR'
    }
  };
}
